from fastapi import FastAPI
from fastapi.testclient import TestClient
from inline_snapshot import snapshot

app = FastAPI()


@app.get("/items", deprecated_at="2025-01-01")
def read_items():
    return [{"name": "Empanada"}, {"name": "Arepa"}]


@app.post("/items", deprecated_at="2025-01-01")
def create_item():
    return {"ok": True}


client = TestClient(app)


def test_get_endpoint_still_responds():
    """Setting deprecated_at should not prevent the endpoint from being reachable."""
    response = client.get("/items")
    assert response.status_code == 200
    assert response.json() == [{"name": "Empanada"}, {"name": "Arepa"}]


def test_post_endpoint_still_responds():
    response = client.post("/items")
    assert response.status_code == 200
    assert response.json() == {"ok": True}


def test_openapi_has_deprecated_true_and_x_deprecated_at():
    response = client.get("/openapi.json")
    assert response.status_code == 200
    assert response.json() == snapshot(
        {
            "openapi": "3.1.0",
            "info": {"title": "FastAPI", "version": "0.1.0"},
            "paths": {
                "/items": {
                    "get": {
                        "summary": "Read Items",
                        "operationId": "read_items_items_get",
                        "deprecated": True,
                        "x-deprecated-at": "2025-01-01",
                        "responses": {
                            "200": {
                                "description": "Successful Response",
                                "content": {
                                    "application/json": {
                                        "schema": {
                                            "items": {
                                                "$ref": "#/components/schemas/Item"
                                            },
                                            "type": "array",
                                            "title": "Response Read Items Items Get",
                                        }
                                    }
                                },
                            }
                        },
                    },
                    "post": {
                        "summary": "Create Item",
                        "operationId": "create_item_items_post",
                        "deprecated": True,
                        "x-deprecated-at": "2025-01-01",
                        "responses": {
                            "200": {
                                "description": "Successful Response",
                                "content": {"application/json": {"schema": {}}},
                            }
                        },
                    },
                }
            },
            "components": {
                "schemas": {
                    "Item": {
                        "properties": {
                            "name": {
                                "title": "Name",
                                "type": "string",
                            }
                        },
                        "required": ["name"],
                        "title": "Item",
                        "type": "object",
                    }
                }
            },
        }
    )


def test_openapi_get_path_is_deprecated_with_x_deprecated_at():
    """Targeted assertion matching the task specification."""
    schema = client.get("/openapi.json").json()
    operation = schema["paths"]["/items"]["get"]
    assert operation["deprecated"] is True
    assert operation["x-deprecated-at"] == "2025-01-01"


def test_deprecated_at_implies_deprecated_flag_on_route():
    """Sanity-check on the route object: deprecated_at sets deprecated=True."""
    route = next(r for r in app.router.routes if getattr(r, "path", None) == "/items")
    assert route.deprecated_at == "2025-01-01"
    assert route.deprecated is True

